    isInteger<valueof<TArray>>() == isInteger<valueof<UArray>>() &&
    alignof<valueof<TArray>>() == alignof<valueof<UArray>>() &&
    !(isSigned<valueof<UArray>>() && target instanceof Uint8ClampedArray)
